import {resourceError} from './resource-error.mjs';
import React,{useState} from 'react';import {useResource} from './state.js';import {TextDiff} from './TextDiff.jsx';import {useDialog} from '../dialog.tsx';
const show=n=>[n.name,n.summary,n.content,'别名：'+(n.aliases||[]).join('、')].filter(Boolean).join('\n\n');
export function MaterialHistory({call,novelId,nodeId,dirty=false,refresh}){const [opened,setOpened]=useState(false),[poll,setPoll]=useState(0),[comparison,setComparison]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),{confirm}=useDialog();const r=useResource(()=>opened?Promise.all([call('graph.get',{novelId,nodeId}),call('graph.history',{novelId,nodeId})]):Promise.resolve(null),[call,novelId,nodeId,opened,poll]);return <details onToggle={e=>setOpened(e.currentTarget.open)}><summary>资料内容历史</summary>{r.error&&<p role="alert">{resourceError(r.error)}<button type="button" onClick={r.retry}>重试</button></p>}{r.value&&<>{!r.value[1].versions.length&&<p>保存修改后，旧版本会保留在这里。</p>}{[...r.value[1].versions].reverse().map(v=><article className="structure-entry" key={v.revision}><strong>版本 {v.revision}</strong><small>{new Date(v.timestamp).toLocaleString()} · {v.reason}</small><div className="row"><button onClick={()=>setComparison(v)}>比较</button><button disabled={busy||dirty} onClick={async()=>{if(!await confirm('恢复资料版本 '+v.revision+'？当前版本会保留在历史中。'))return;setBusy(true);setError('');try{await call('graph.restore',{novelId,nodeId,expectedRevision:r.value[0].revision,targetRevision:v.revision,requestId:crypto.randomUUID()});setPoll(n=>n+1);setComparison(null);refresh?.();}catch(e){setError(resourceError(e));}finally{setBusy(false);}}}>恢复</button></div></article>)}{comparison&&<TextDiff before={show(comparison.value)} after={show(r.value[0])} beforeLabel={'版本 '+comparison.revision} afterLabel="当前资料"/>}</>}{error&&<p role="alert">{error}</p>}</details>;}
